<!doctype html><html lang="<?=$e($context['locale'])?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$t('Contacto y ayuda')?> | Explorando Lugares</title><?=PortalPresentation::assets(true,'public','css')?><link rel="stylesheet" href="/assets/account-registration.css"><link rel="stylesheet" href="<?=$e($identity)?>"><?=PortalPresentation::assets(true,'public','js')?></head><body class="portal-account-page"><?=PortalPresentation::header($context)?><main class="wrap account-portal"><p><a href="<?=$e($prefix)?>/"><?=$t('← Volver al portal')?></a></p><h1><?=$t('Contacto y ayuda')?></h1><section class="account-portal-card"><h2><?=$t('¿Cómo podemos ayudarte?')?></h2><p><a href="<?=$e($prefix)?>/negocios-locales/interes/"><?=$t('Necesito información para mi negocio →')?></a></p><p><a href="<?=$e($prefix)?>/negocios-locales/impulsor/"><?=$t('Quiero promover la plataforma en mi lugar →')?></a></p><h2><?=$t('Sugerencias y solicitudes')?></h2><p><?=$t('No necesitas una cuenta. Usaremos tu correo para atender y responder esta solicitud; no te suscribiremos a publicidad.')?></p><?php if($data['reference']):?><p role="status"><?=$t('Solicitud registrada. Tu referencia es')?> <strong><?=$e((string)$data['reference'])?></strong>. <?=$t('Conserva este número para consultar con nuestro equipo.')?></p><?php endif;?><?php if($data['error']):?><p role="alert"><?=$e($data['error'])?></p><?php endif;?><form method="post" class="registration-form"><input type="hidden" name="csrf" value="<?=$e($data['csrf'])?>"><label><?=$t('Tipo de solicitud')?><select name="request_type" required><?php foreach($data['types'] as $code=>$label):?><option value="<?=$e($code)?>"><?=$t($label)?></option><?php endforeach;?></select></label><label><?=$t('Nombre')?><input name="name" maxlength="180" required value="<?=$e($data['input']['name']??'')?>"></label><label><?=$t('Correo para responderte')?><input type="email" name="email" maxlength="254" required value="<?=$e($data['input']['email']??'')?>"></label><label><?=$t('Cuéntanos qué necesitas')?><textarea name="message" minlength="10" maxlength="10000" rows="6" required><?=$e($data['input']['message']??'')?></textarea></label><label><input type="checkbox" name="consent" value="1" required><?=$t('Autorizo el uso de estos datos para atender la solicitud, según la')?> <a href="<?=$e($prefix)?>/privacidad/"><?=$t('política de privacidad')?></a>.</label><label hidden>No completar<input name="website" tabindex="-1" autocomplete="off"></label><button class="pill" type="submit"><?=$t('Registrar solicitud')?></button></form></section></main><?=PortalPresentation::footer($context)?></body></html>
